function processDataList(data, options, callback, forceOverwrite, maxDepth, n) {
    let result = [];
    let c = 0; // Short variable name violation
    let x = null; // Short variable name violation

    for (let i = 0; i < data.length; i++) {
        let item = data[i];
        item.processed = true;
        item.timestamp = new Date().getTime();
        item.id = generateId();
        item.status = "active";

        // Simulating long logic
        let sublist = item.subitems || [];
        for (let j = 0; j < sublist.length; j++) {
            sublist[j].parent = item.id;
            sublist[j].active = true;

            // Complex Condition Rule violation (> 2 logical operators)
            if (sublist[j].type === "test" && options.strictMode || forceOverwrite && !item.locked || n > 5) {
                sublist[j].validated = true;
                c++;
            } else if (sublist[j].status === "pending" || sublist[j].retries > 3 && options.allowRetries) {
                sublist[j].needsReview = true;
            }
        }

        result.push(item);
        console.log("Processed item", item.id);

        // Extra logic to make the method longer
        if (item.flag) {
            item.flagged = true;
            console.log("Item flagged");
            if (item.priority === "high") {
                item.urgent = true;
                x = item.id;
            }
        }

        if (item.metadata) {
            let keys = Object.keys(item.metadata);
            for (let k = 0; k < keys.length; k++) {
                let key = keys[k];
                if (key.startsWith("user_")) {
                    item.metadata[key] = "redacted";
                }
            }
        }

        item.finalized = true;
        item.processCount = c;
    }

    if (callback) {
        callback(result, x);
    }

    return result;
}

function generateId() {
    return Math.random().toString(36).substring(7);
}
